@namespace sv_a12313d911544ad5a768d1b7af211cb8.Components.Pages.Apply

<div class="step-indicator d-flex justify-content-between mb-4">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isCompleted = step < CurrentStep;
        var isCurrent = step == CurrentStep;
        var isFuture = step > CurrentStep;

        <div class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
             role="button"
             @onclick="() => HandleStepClick(step)"
             style="cursor: @(isCompleted ? "pointer" : "default"); opacity: @(isFuture ? "0.4" : "1");">
            <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                 style="width: 36px; height: 36px; font-size: 0.9rem;">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <small class="@(isCurrent ? "fw-bold text-primary" : "")">@StepNames[i]</small>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

